{
  "tools": [
    {
      "name": "asset_compile",
      "title": "Asset Compile",
      "toolset": "asset",
      "description": "Recompile an asset from its source file. Compile errors and warnings land in the console - check read_console after a failure.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Asset path, as returned by asset_search."
          },
          "full": {
            "type": "boolean",
            "description": "Force a full recompile instead of an incremental one.",
            "default": false
          }
        },
        "required": [
          "path"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Success": {
            "type": "boolean"
          },
          "Path": {
            "type": "string"
          },
          "CompiledFile": {
            "type": "string"
          },
          "Hint": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "asset_search",
      "title": "Asset Search",
      "toolset": "asset",
      "description": "Search the asset system by keywords and type. An empty query lists every asset, so use limit and offset to page through. Returns relative asset paths - pass one to asset_info, asset_compile, asset_read or asset_dependencies.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "Space separated keywords. Every keyword must match the asset's path or one of its tags. Empty matches everything."
          },
          "type": {
            "type": "string",
            "description": "Filter to one asset type - a file extension (vmdl, vmat, prefab) or friendly name (Model, Material). See asset_types."
          },
          "projectOnly": {
            "type": "boolean",
            "description": "Only assets belonging to the currently open project, excluding engine content and cloud downloads.",
            "default": false
          },
          "unreferencedOnly": {
            "type": "boolean",
            "description": "Only assets nothing else references - useful for finding unused assets. Note map files and code can use an asset without the asset system knowing.",
            "default": false
          },
          "compileFailedOnly": {
            "type": "boolean",
            "description": "Only assets whose last compile failed.",
            "default": false
          },
          "uncompiledOnly": {
            "type": "boolean",
            "description": "Only assets with no compiled version at all.",
            "default": false
          },
          "limit": {
            "type": "integer",
            "description": "How many results to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 50
          },
          "offset": {
            "type": "integer",
            "description": "How many results to skip, for paging.",
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many assets matched in total, beyond this page."
          },
          "Showing": {
            "type": "integer"
          },
          "Offset": {
            "type": "integer"
          },
          "Assets": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Path": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}

{
  "tools": [
    {
      "name": "compile_status",
      "title": "Compile Status",
      "toolset": "editor",
      "description": "The live state of the project's code compilers - is anything building, did each compiler's last build succeed, and every error and warning with file and line. This is how you check whether a code edit hotloaded cleanly.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsBuilding": {
            "type": "boolean",
            "description": "Whether anything is building right now."
          },
          "Compilers": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string",
                  "description": "The project this compiler builds, like 'base' or 'facepunch.sandbox'."
                },
                "IsBuilding": {
                  "type": "boolean"
                },
                "NeedsBuild": {
                  "type": "boolean"
                },
                "Success": {
                  "type": "boolean",
                  "description": "Whether the last build succeeded. Null when it hasn't built yet."
                },
                "Errors": {
                  "type": "integer"
                },
                "Warnings": {
                  "type": "integer"
                },
                "Diagnostics": {
                  "type": "array",
                  "items": {},
                  "description": "The last build's errors and warnings, errors first, capped at 50."
                }
              },
              "required": []
            },
            "description": "Every compiler, each with its last build's outcome."
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}

{
  "tools": [
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "editor_camera_screenshot",
      "title": "Editor Camera Screenshot",
      "toolset": "scene",
      "description": "Render what the editor scene camera sees and return it as an image - see the scene the way the viewport does. Move the view first with set_editor_camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_find_hidden_faces",
      "title": "Find Hidden Faces",
      "toolset": "hammer",
      "description": "Find mesh faces nobody can see because they're buried inside or pressed flat against other geometry - the underside of a crate sitting on a floor, wall ends tucked into other walls. They still cost rendering and lightmap space. By default this only reports; set apply to paint them nodraw (or another material) in one undo step. A face counts as hidden only if every sample point on it is enclosed by opaque, non-tools mesh geometry, so partly covered faces are left alone. Meshes that aren't closed can fool it - check the result with hammer_focus_nodes and hammer_screenshot before applying on a map you care about.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "Mesh node ids to check. Empty checks every mesh."
          },
          "apply": {
            "type": "boolean",
            "description": "Paint the hidden faces with 'material'. False only reports them.",
            "default": false
          },
          "material": {
            "type": "string",
            "description": "The material to paint hidden faces with.",
            "default": "materials/tools/toolsnodraw.vmat"
          },
          "limit": {
            "type": "integer",
            "description": "How many meshes to list in the report.",
            "minimum": 1,
            "maximum": 1000,
            "default": 100
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_focus_nodes",
      "title": "Focus Nodes",
      "toolset": "hammer",
      "description": "Select nodes and frame every Hammer view on them, like the user pressing the frame selection key - the quickest way to show the user something, or to aim hammer_screenshot at it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "ids": {
            "type": "array",
            "items": {
              "type": "integer"
            },
            "description": "The node ids to frame."
          }
        },
        "required": [
          "ids"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Mode": {
            "type": "string"
          },
          "Pivot": {
            "type": "string"
          },
          "Count": {
            "type": "integer"
          },
          "Nodes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "integer"
                },
                "Kind": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "ClassName": {
                  "type": "string"
                },
                "Description": {
                  "type": "string"
                },
                "Position": {
                  "type": "string"
                },
                "Parent": {
                  "type": "integer"
                },
                "GameObject": {
                  "type": "string"
                },
                "Selected": {
                  "type": "boolean"
                },
                "Visible": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_screenshot",
      "title": "Screenshot",
      "toolset": "hammer",
      "description": "Render the map as Hammer's 3D view draws it and return the image - see what you've built. Renders from the main 3D view's camera unless you give a camera, which doesn't move the user's view. Aim it with hammer_focus_nodes or hammer_set_camera first, or pass position and lookAt.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "position": {
            "type": "string",
            "description": "Camera position as 'x,y,z'. Empty uses the 3D view's camera."
          },
          "angles": {
            "type": "string",
            "description": "Camera angles as 'pitch,yaw,roll'."
          },
          "lookAt": {
            "type": "string",
            "description": "A point to look at as 'x,y,z' - overrides angles."
          },
          "fieldOfView": {
            "type": "number",
            "description": "Field of view in degrees. 0 uses the 3D view's.",
            "minimum": 0,
            "maximum": 170,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_pixels",
      "title": "Pixels",
      "toolset": "ui",
      "description": "Read exact pixel values out of a panel - the numbers behind ui_screenshot, for when looking at an image isn't an answer. Points are relative to the panel's top left, which is what makes them comparable to a browser's readout of the same case. Values are 0-255, straight off the rendered frame.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector. Empty uses the first root."
          },
          "points": {
            "type": "string",
            "description": "Points to read, as 'x,y x,y x,y'. Empty reads the panel's centre."
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_probe",
      "title": "Probe",
      "toolset": "ui",
      "description": "Draw a scratch panel with the css you give it, measure it, screenshot it, then throw it away. This is how you try a declaration without editing a file and waiting for a hotload - state a case, see what it renders to, compare it against a browser. The sample is a 100x100 block, or a label when you give it text, both inset in a cell like tools/uiparity draws them.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "css": {
            "type": "string",
            "description": "The css to try, e.g. 'border-radius: 20px; background-color: #e8b04a'."
          },
          "text": {
            "type": "string",
            "description": "Text to draw, which makes the sample a label instead of a block."
          },
          "background": {
            "type": "string",
            "description": "Colour behind the sample, so anything with alpha reads against something known.",
            "default": "#101010"
          },
          "points": {
            "type": "string",
            "description": "Pixels to read, as 'x,y x,y' relative to the sample. Empty reads its centre."
          },
          "screenshot": {
            "type": "boolean",
            "description": "Return an image as well as the numbers.",
            "default": true
          }
        },
        "required": [
          "css"
        ]
      }
    },
    {
      "name": "ui_probe_batch",
      "title": "Probe Batch",
      "toolset": "ui",
      "description": "Probe a whole list of css cases at once - one cell each, laid out in a grid, measured together and captured as a single contact sheet. This is the parity sweep: state the cases, get every measurement back in one call, then diff them against the same cases in a browser.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "cases": {
            "type": "string",
            "description": "One css case per line. Lines starting with # are ignored, so a case file pastes straight in."
          },
          "text": {
            "type": "string",
            "description": "Text to draw, which makes every sample a label instead of a block."
          },
          "background": {
            "type": "string",
            "description": "Colour behind the samples.",
            "default": "#101010"
          },
          "columns": {
            "type": "integer",
            "description": "Cells per row. 0 fits as many as the screen holds.",
            "minimum": 0,
            "maximum": 24,
            "default": 0
          },
          "points": {
            "type": "string",
            "description": "Pixels to read from every sample, as 'x,y x,y'. Empty reads their centres."
          },
          "screenshot": {
            "type": "boolean",
            "description": "Return the contact sheet as well as the numbers.",
            "default": true
          }
        },
        "required": [
          "cases"
        ]
      }
    },
    {
      "name": "ui_screenshot",
      "title": "Screenshot",
      "toolset": "ui",
      "description": "A screenshot of one panel, cropped to its screen rect, so you can look at what a panel actually draws without hunting for it in a full frame. Renders through the running scene's camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector. Empty uses the first root."
          },
          "padding": {
            "type": "integer",
            "description": "Extra pixels around the panel, for seeing shadows and outlines.",
            "minimum": 0,
            "maximum": 512,
            "default": 0
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "ui_set_pseudo",
      "title": "Set Pseudo",
      "toolset": "ui",
      "description": "Force a pseudo class on a panel - hover, active, focus - so its styles can be looked at and screenshotted without a mouse. Clears again with on false.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "panel": {
            "type": "string",
            "description": "Panel path from ui_panel_dump, or a selector."
          },
          "pseudo": {
            "type": "string",
            "description": "Which one, e.g. 'Hover'."
          },
          "on": {
            "type": "boolean",
            "description": "Set it, or clear it.",
            "default": true
          }
        },
        "required": [
          "panel",
          "pseudo"
        ]
      }
    }
  ],
  "total": 128
}
